window.MAP_DATA_RECORDS.push(...[{"i":"R2963","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Oversight board meta israel hamas","s":"The board is going to look at two posts removed for violating Meta’s policies against sharing graphic imagery and depicting dangerous organizations and individuals. Today, Meta’s Oversight Board announced it would take on two expedited cases, the first ever, both dealing with the ongoing conflict between Israel and Hamas. The case will look at two posts that were initially removed from and then reinstated on Instagram and Facebook for violating Meta’s policies against sharing graphic imagery and depicting dangerous organizations and individuals, respectively. One of the posts showed the aftermath of the attack on Al-Shifa Hospital by the Israel Defense Forces, and the other was a video of an Israeli hostage being taken by Hamas on October 7.","u":"https://www.wired.com/story/oversight-board-meta-israel-hamas/","d":"2023-12-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-07","organization":"Meta (Facebook and Instagram)","aiSystem":"Meta's content moderation system","affectedGroup":"People who posted content related to the conflict","action":"Posts were initially removed and then reinstated due to policy violations","consequence":"Content was removed and later restored, causing confusion and potential misinformation"}},{"i":"R2964","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Inside americas school internet censorship machine","s":"A WIRED investigation into internet censorship in US schools found widespread use of filters to censor health, identity, and other crucial information. Students say it makes the web entirely unusable. Around dinner time one night in May, a student in Albuquerque, New Mexico, Googled “Obergefell v. Hodges ruling.” But instead of a list of links to information about the landmark US Supreme Court case that legalized same-sex marriage, the 11th grader from La Cueva High School was redirected to a gray screen with Albuquerque Public Schools’ logo and the message: “Restricted. This website has been blocked by your administrator.”","u":"https://www.wired.com/story/inside-americas-school-internet-censorship-machine/","d":"2023-12-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"May","organization":"Albuquerque Public Schools","aiSystem":"Internet filtering systems","affectedGroup":"Students, particularly those in La Cueva High School","action":"Blocked websites containing sensitive information","consequence":"Restriction of access to crucial information, including legal rulings"}},{"i":"R2965","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Chatgpt poem forever security roundup","s":"Plus: A major ransomware crackdown, the arrest of Ukraine's cybersecurity chief, and a hack-for-hire entrepreneur charged with attempted murder. Brinkmanship escalated in the US Congress this week over strategies to reauthorize the government surveillance powers known as “Section 702,” as civil rights groups sounded the alarm about the consequences of the program and its potential renewal. A WIRED investigation of more than 100 restricted Telegram channels indicated that the communication app's bans on extremist discourse aren't effective or adequate bans. And the identity management platform Okta admitted this week that a security breach previously thought to impact 1 percent of its customers actually affected 100 percent.","u":"https://www.wired.com/story/chatgpt-poem-forever-security-roundup/","d":"2023-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-02","organization":"Okta","aiSystem":"Not specified in report","affectedGroup":"Customers of Okta","action":"Admitted to a security breach","consequence":"Affected 100% of customers"}},{"i":"R2966","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Social media ai dead bodies","s":"Poverty, fentanyl, and lack of public funding mean morgues are overloaded with unidentified bodies. TikTok and Facebook pages are filling the gap—with AI proving a powerful and controversial new tool. Content Warning: This story includes references to suicide. If you need help, call the Suicide and Crisis Lifeline for your region. In 2021, an unidentified Black woman died by suicide after jumping off the Brooklyn Bridge. She was wearing hot-pink nail polish, and had a pink left eyebrow piercing and several tattoos—all distinguishing features that should have made it easier to identify her. Two years later, her identity is still unknown.","u":"https://www.wired.com/story/social-media-ai-dead-bodies/","d":"2023-11-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021","organization":"Social media platforms (TikTok and Facebook)","aiSystem":"AI-powered identification tools","affectedGroup":"Unidentified deceased individuals","action":"Used AI to generate identifying features","consequence":"Increased privacy risks for unidentified deceased"}},{"i":"R2968","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Johnny cash artificial intelligence taylor swift barbie girl covers music future","s":"With covers of “Blank Space” and Aqua's “Barbie Girl” going viral, Johnny Cash is suddenly the voice of AI. The choice is telling. When Texas-based copywriter Dustin Ballard released a cover of Aqua’s 1997 Europop hit “Barbie Girl” this summer using an AI-generated version of Johnny Cash’s voice, he was surprised by its reception. “I actually expected more of a backlash,” he says. Earlier this fall, when he followed up with AI Johnny Cash singing Taylor Swift ’s “Blank Space,” the feedback was unexpectedly positive once again. “This is hauntingly beautiful,” the top comment reads. Media coverage skewed glowing. “It absolutely slaps,” Futurism wrote.","u":"https://www.wired.com/story/johnny-cash-artificial-intelligence-taylor-swift-barbie-girl-covers-music-future/","d":"2023-11-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-06","organization":"Dustin Ballard (copywriter)","aiSystem":"AI-generated voice synthesis technology","affectedGroup":"Johnny Cash's voice","action":"AI-generated voice synthesizing Johnny Cash's voice","consequence":"Unexpected positive reception and media coverage"}},{"i":"R2970","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Amazons ai van inspections powerful data feed","s":"Amazon delivery drivers at hundreds of sites around the world will be asked to drive through camera-studded archways that log every dent, scratch, or damaged tire. Amazon is splashing out on new vehicle inspectors to watch for damage or wear to its vast fleet of delivery vans—and they’re not human. The retailer is installing camera-studded inspection stations equipped with artificial intelligence-powered technology called AVI, or automated vehicle inspection, at hundreds of its distribution centers worldwide. When a driver working out of any of the 20 delivery centers currently equipped with the tech returns their vehicle at the end of a shift, they slowly drive it through a sensor-laden archway made by startup UVeye, which has headquarters in the US and Israel.","u":"https://www.wired.com/story/amazons-ai-van-inspections-powerful-data-feed/","d":"2023-10-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-24","organization":"Amazon","aiSystem":"Automated Vehicle Inspection (AVI) system","affectedGroup":"Amazon delivery drivers","action":"Slowly drive their vehicle through a sensor-laden archway equipped with AI technology","consequence":"Their vehicles are inspected for damage or wear by an AI-powered system"}},{"i":"R2971","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Cruise robotaxi self driving permit revoked california","s":"The California DMV says the company’s autonomous taxis are “not safe” and that Cruise “misrepresented” safety information about its self-driving vehicle technology. California has suspended driverless vehicles operated by the General Motors subsidiary Cruise in the city of San Francisco—just two months after the state began allowing the robotaxis to pick up paying passengers around the clock. The suspension stems from a gruesome incident on October 2 in which a human-driven vehicle hit a female pedestrian and threw her into the path of a Cruise car. The driverless Cruise car hit her, stopped, and then tried to pull over, dragging her approximately 20 feet.","u":"https://www.wired.com/story/cruise-robotaxi-self-driving-permit-revoked-california/","d":"2023-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-02","organization":"General Motors subsidiary Cruise","aiSystem":"self-driving vehicle technology","affectedGroup":"female pedestrian","action":"hit a female pedestrian and threw her into the path of a Cruise car","consequence":"dragged her approximately 20 feet"}},{"i":"R2976","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Soundthinking geolitica acquisition predictive policing","s":"SoundThinking is purchasing parts of Geolitica, the company that created PredPol. Experts say the acquisition marks a new era of companies dictating how police operate. SoundThinking, the company behind the gunshot-detection system ShotSpotter, is quietly acquiring staff, patents, and customers of the firm that created the notorious predictive policing software PredPol, WIRED has learned. In an August earnings call, SoundThinking CEO Ralph Clark announced to investors that the company was negotiating an agreement to acquire parts of Geolitica—formerly called PredPol—and transition its customers to SoundThinking’s own “patrol management” solution.","u":"https://www.wired.com/story/soundthinking-geolitica-acquisition-predictive-policing/","d":"2023-09-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-27","organization":"SoundThinking","aiSystem":"Predictive policing algorithm","affectedGroup":"Job applicants","action":"Transitioned customers to SoundThinking's patrol management solution","consequence":"Created unequal outcomes for applicants"}},{"i":"R2977","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Fbi agents face recognition without proper training","s":"The FBI makes heavy use of face recognition services like that of controversial startup Clearview AI, but 95 percent of the agents using them haven’t completed training on the technology. The US Federal Bureau of Investigation (FBI) has done tens of thousands of face recognition searches using software from outside providers in recent years. Yet only 5 percent of the 200 agents with access to the technology have taken the bureau’s three-day training course on how to use it, a report from the Government Accountability Office (GAO) this month reveals. The bureau has no policy for face recognition use in place to protect privacy, civil rights, or civil liberties.","u":"https://www.wired.com/story/fbi-agents-face-recognition-without-proper-training/","d":"2023-09-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-25","organization":"US Federal Bureau of Investigation (FBI)","aiSystem":"face recognition technology","affectedGroup":"agents with access to the technology","action":"performed face recognition searches","consequence":"lack of proper training and privacy protection policies"}},{"i":"R2979","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Local governments generative ai","s":"State and local governments in the US are scrambling to harness tools like ChatGPT to unburden their bureaucracies, rushing to write their own rules—and avoid generative AI's many pitfalls. The United States Environmental Protection Agency blocked its employees from accessing ChatGPT while the US State Department staff in Guinea used it to draft speeches and social media posts. Maine banned its executive branch employees from using generative artificial intelligence for the rest of the year out of concern for the state’s cybersecurity. In nearby Vermont, government workers are using it to learn new programming languages and write internal-facing code, according to Josiah Raiche, the state’s director of artificial intelligence.","u":"https://www.wired.com/story/local-governments-generative-ai/","d":"2023-09-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-11","organization":"State and local governments in the United States","aiSystem":"Generative AI systems like ChatGPT","affectedGroup":"Government employees","action":"Using generative AI systems for various tasks","consequence":"Potential exposure to cybersecurity risks and privacy issues"}},{"i":"R2980","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Your new car privacy nightmare","s":"Plus: Apple patches newly discovered flaws exploited by NSO Group spyware, North Korean hackers target security researchers, and more. Last week, WIRED published a deep-dive investigation into Trickbot , the prolific Russian ransomware gang. This week, US and UK authorities sanctioned 11 alleged members of Trickbot and its related group, Conti , including Maksim Galochkin, aka Bentley, one of the alleged members whose real-world identity we confirmed through our investigation. Coincidence? Maybe. Either way, it's a big deal. In addition to the US and UK sanctions, the US Justice Department also unsealed indictments filed in three US federal courts against Galochkin and eight other alleged Trickbot members for ransomware attacks against entities in Ohio, Tennessee, and California.","u":"https://www.wired.com/story/your-new-car-privacy-nightmare/","d":"2023-09-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-09","organization":"US and UK authorities, US Justice Department","aiSystem":"Not specified in report","affectedGroup":"Entities in Ohio, Tennessee, and California","action":"Sanctioned and indicted for ransomware attacks","consequence":"Potential exposure to cyber threats and surveillance"}},{"i":"R2981","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Axon taser drones ethics board","s":"The CEO’s vision for Taser-equipped drones includes a fictitious scenario in which the technology averts a shooting at a day care center. This article was copublished with The Markup, a nonprofit, investigative newsroom that challenges technology to serve the public good. Sign up for its newsletters here Less than 10 days after the Robb Elementary School shooting in Uvalde, Texas, in May 2022, Axon Enterprises CEO Rick Smith announced the company had formally started developing Taser-equipped drones. The technology, Smith argued, could potentially save lives during mass shootings by incapacitating active shooters within seconds.","u":"https://www.wired.com/story/axon-taser-drones-ethics-board/","d":"2023-09-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"Less than 10 days after the Robb Elementary School shooting in Uvalde, Texas, in May 2022","organization":"Axon Enterprises","aiSystem":"Taser-equipped drones","affectedGroup":"Active shooters","action":"Used to incapacitate active shooters","consequence":"Potential wrongful death"}},{"i":"R2984","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Ubers fatal self driving car crash saga over operator avoids prison","s":"After five years of purgatory, Rafaela Vasquez, the operator of a self-driving Uber that killed a pedestrian in 2018, pleaded guilty to endangerment. It’s been more than five years since an Uber self-driving car struck and killed a woman named Elaine Herzberg as she walked her bicycle across a road in Tempe, Arizona. Herzberg’s death instantly turned what had been a philosophical conundrum into a glaringly real, legal one: Who gets blamed for a road fatality in the awkward, liminal era of self-driving cars, when humans are essentially babysitters of imperfect, still-learning AI systems? Is it the company with the erring car?","u":"https://www.wired.com/story/ubers-fatal-self-driving-car-crash-saga-over-operator-avoids-prison/","d":"2023-07-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018-10-03","organization":"Uber","aiSystem":"self-driving Uber car","affectedGroup":"Elaine Herzberg","action":"struck and killed a pedestrian","consequence":"instantly turned into a legal issue"}},{"i":"R2990","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatgpt prompt injection attack security","s":"Indirect prompt-injection attacks can leave people vulnerable to scams and data theft when they use the AI chatbots. Sydney is back. Sort of. When Microsoft shut down the chaotic alter ego of its Bing chatbot , fans of the dark Sydney personality mourned its loss But one website has resurrected a version of the chatbot—and the peculiar behavior that comes with it. Bring Sydney Back was created by Cristiano Giardina, an entrepreneur who has been experimenting with ways to make generative AI tools do unexpected things. The site puts Sydney inside Microsoft’s Edge browser and demonstrates how generative AI systems can be manipulated by external inputs.","u":"https://www.wired.com/story/chatgpt-prompt-injection-attack-security/","d":"2023-05-25","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-05-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-25","organization":"Microsoft","aiSystem":"Generative AI chatbot","affectedGroup":"Individuals using Microsoft Edge browser","action":"Manipulate generative AI systems with external inputs","consequence":"Vulnerability to scams and data theft"}},{"i":"R2991","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Content moderation language artificial intelligence","s":"Social media companies claim new language models can remove harmful content in every language. But those systems’ shortcomings can have vast consequences. Three parts Bosnian text. Thirteen parts Kurdish. Fifty-five parts Swahili. Eleven thousand parts English. This is part of the data recipe for Facebook’s new large language model, which the company claims is able to detect and rein in harmful content in over 100 languages. Bumble uses similar technology to detect rude and unwanted messages in at least 15 languages. Google uses it for everything from translation to filtering newspaper comment sections. All have comparable recipes and the same dominant ingredient: English-language data.","u":"https://www.wired.com/story/content-moderation-language-artificial-intelligence/","d":"2023-05-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-23","organization":"Facebook, Bumble, Google","aiSystem":"Large language model","affectedGroup":"People posting content in various languages","action":"Used to detect and remove harmful content","consequence":"Vast consequences including potential misuse of English-language data"}},{"i":"R2992","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Cnet published ai generated stories then its staff pushed back","s":"Like Hollywood's striking screenwriters, the outlet's employees want protections against potentially job-killing automation. In November, venerable tech outlet CNET began publishing articles generated by artificial intelligence, on topics such as personal finance, that proved to be riddled with errors Today the human members of its editorial staff have unionized, calling on their bosses to provide better conditions for workers and more transparency and accountability around the use of AI. “In this time of instability, our diverse content teams need industry-standard job protections, fair compensation, editorial independence, and a voice in the decisionmaking process, especially as automated technology threatens our jobs and reputations,” reads the mission statement of the CNET Media Workers Union, whose more than 100 members include writers, editors, video producers, and other content…","u":"https://www.wired.com/story/cnet-published-ai-generated-stories-then-its-staff-pushed-back/","d":"2023-05-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-16","organization":"CNET","aiSystem":"AI-generated stories","affectedGroup":"human members of its editorial staff","action":"published articles generated by artificial intelligence","consequence":"called on their bosses to provide better conditions for workers and more transparency and accountability"}},{"i":"R2993","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Unfair automated hiring systems are everywhere ftc","s":"Algorithms can exacerbate employment discrimination. It's time for the US Federal Trade Commission to regulate them. Earlier this month, Lina Khan, chair of the US Federal Trade Commission (FTC), wrote an essay in The New York Times affirming the agency’s commitment to regulating AI. But there was one AI application Khan didn’t mention that the FTC urgently needs to regulate: automated hiring systems. These range in complexity from tools that merely parse resumes and rank them to systems that green-light candidates and trash applicants deemed unfit. Increasingly, working Americans are obligated to use them if they want to get hired.","u":"https://www.wired.com/story/unfair-automated-hiring-systems-are-everywhere-ftc/","d":"2023-05-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-15","organization":"US Federal Trade Commission (FTC)","aiSystem":"Automated hiring algorithms","affectedGroup":"Job applicants","action":"Rank job applicants","consequence":"Created unequal outcomes for applicants"}},{"i":"R2994","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Safegraph us air force location data","s":"Documents obtained by WIRED show SafeGraph, which sold location data related to Planned Parenthood visits, is now pursuing contracts with the US Air Force. The data broker made famous for selling location data related to abortion clinic visits has signed a contract with the US Air Force and plans to provide information about “sensitive places” and “adversary state-owned enterprises” around the world, according to records obtained by WIRED. The company, SafeGraph, told the military that its data can be used for “analyzing human activity for landing zone selection,” as well as to identify hospitals, schools, and houses of worship to “help avoid collateral damage.”","u":"https://www.wired.com/story/safegraph-us-air-force-location-data/","d":"2023-05-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-08","organization":"SafeGraph","aiSystem":"SafeGraph's location data","affectedGroup":"People visiting sensitive places and adversary state-owned enterprises around the world","action":"Providing location data for analysis and identification of critical infrastructure","consequence":"Potential misuse for military purposes leading to surveillance and targeting of civilians"}},{"i":"R2995","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ice agent database abuse records","s":"Documents obtained by WIRED detail hundreds of investigations by the US agency into alleged database misuse that includes harassment, stalking, and more. Since 2016, hundreds of US Immigration and Customs Enforcement employees and contractors have faced internal investigations into abuse of confidential law enforcement databases and agency computers. The alleged misconduct includes a swath of unlawful behavior, from stalking and harassment to passing information to criminals. ICE says these databases are vital tools for enforcing the law. However, agency records of internal misconduct investigations reveal that they can also be used to subvert it.","u":"https://www.wired.com/story/ice-agent-database-abuse-records/","d":"2023-04-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2016-present","organization":"US Immigration and Customs Enforcement (ICE)","aiSystem":"Law enforcement databases","affectedGroup":"US Immigration and Customs Enforcement employees and contractors","action":"Internal investigations into abuse of confidential law enforcement databases and agency computers","consequence":"Subversion of law enforcement efforts"}},{"i":"R2997","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Dashcam footage shows driverless cars cruise waymo clogging san francisco","s":"Videos obtained by WIRED from public transit vehicles reveal self-driving cars causing delays and potential danger to buses, trains, and passengers. The bus was stuck. San Francisco’s eastbound 54 Felton line was heading up a narrow residential street when a white SUV coming the other way stopped in the middle of the road. It was a rainy Sunday evening last month, and the bus driver leaned up to the windshield and peered through the haze at the SUV’s pulsing hazard lights before slumping back and exclaiming in surprise, \"What the hell? No driver of the car?!\" The 54, brought to a halt by an autonomous vehicle belonging to Alphabet’s Waymo, isn’t the only bus that’s run into trouble with San Francisco’s growing crowd of driverless vehicles.","u":"https://www.wired.com/story/dashcam-footage-shows-driverless-cars-cruise-waymo-clogging-san-francisco/","d":"2023-04-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-10","organization":"Alphabet's Waymo","aiSystem":"self-driving cars","affectedGroup":"San Francisco’s eastbound 54 Felton line","action":"blocked the bus","consequence":"causing delays and potential danger to buses, trains, and passengers"}},{"i":"R3003","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Welfare fraud industry","s":"When systems designed to catch welfare cheats go wrong, people find themselves trapped between secretive governments and even more opaque private companies. Mitch Daniels is a numbers guy, a cost-cutter. In the early 2000s, he tried and failed to rein in congressional spending under then-US president George W. Bush. So when he took office as Indiana governor in 2005, Daniels was ready to argue once again for fiscal discipline. He wanted to straighten out Indiana’s state government, which he deemed rife with dysfunction. And he started with its welfare system. “That department had been rocked by a series of criminal indictments, with cheats and caseworkers colluding to steal money meant for poor people,” he later said.","u":"https://www.wired.com/story/welfare-fraud-industry/","d":"2023-03-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2005","organization":"Indiana state government","aiSystem":"AI-powered welfare fraud detection system","affectedGroup":"welfare recipients","action":"used AI to identify and deny welfare benefits","consequence":"people found themselves trapped between secretive governments and private companies"}},{"i":"R3007","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Algorithms allegedly penalized black renters the us government is watching","s":"The Department of Justice warned a provider of tenant-screening software that its technology must comply with fair housing law. Two years ago, Mary Louis submitted an application to rent an apartment at Granada Highlands in Malden, Massachusetts. She liked that the unit had two full bathrooms and that there was a pool on the premises. But the landlord denied her the apartment, allegedly due to a score assigned to her by a tenant-screening algorithm made by SafeRent. Louis responded with references to prove 16 years of punctual rent payments, to no avail. Instead she took a different apartment that cost $200 more a month in an area with a higher crime rate.","u":"https://www.wired.com/story/algorithms-allegedly-penalized-black-renters-the-us-government-is-watching/","d":"2023-01-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-01-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021","organization":"SafeRent","aiSystem":"tenant-screening algorithm","affectedGroup":"Black renters","action":"assigned a score to applicants","consequence":"denied rental applications"}},{"i":"R3010","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"San franciscos killer police robots threaten the citys most vulnerable","s":"Law enforcement says that in some scenarios a lethal robot is the only way to protect public safety. Experts say the policy will harm communities of color. Three years ago, the San Francisco Board of Supervisors made history by becoming the first city in the nation to ban use of facial recognition technology by local government. Last night, the board went in a different direction, giving police the right to kill a criminal suspect with a teleoperated robot if they believe there is an imminent threat of death to police or members of the public. Assistant police chief David Lazar said ahead of the vote that killer robots might be needed in scenarios involving mass shootings or suicide bombers, citing the Mandalay Bay shooting in Las Vegas in 2017 and the killing of five police officers in Dallas, Texas, in 2016.","u":"https://www.wired.com/story/san-franciscos-killer-police-robots-threaten-the-citys-most-vulnerable/","d":"2022-12-01","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-12-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-01","organization":"San Francisco Police Department","aiSystem":"Teleoperated lethal robots","affectedGroup":"Criminal suspects","action":"Kill a criminal suspect with a teleoperated robot","consequence":"Exposure to lethal force"}},{"i":"R3012","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Mental health chatbots","s":"With human therapists in short supply, AI chatbots are trying to plug the gap—but it’s not clear how well they work. Teresa Berkowitz’s experiences with therapists had been hit or miss. ”Some good, some helpful, some just a waste of time and money,” she says. When some childhood trauma was reactivated six years ago, instead of connecting with a flesh-and-blood human, Berkowitz—who’s in her fifties and lives in the US state of Maine—downloaded Youper, a mental health app with a chatbot therapist function powered by artificial intelligence. Once or twice a week Berkowitz does guided journaling using the Youper chatbot, during which the bot prompts her to spot and change negative thinking patterns as she writes down her thoughts.","u":"https://www.wired.com/story/mental-health-chatbots/","d":"2022-10-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-01","organization":"Not specified in report","aiSystem":"Mental health app with a chatbot therapist function powered by artificial intelligence","affectedGroup":"Individuals seeking mental health support","action":"Chatbot therapist prompts users to spot and change negative thinking patterns during guided journaling sessions","consequence":"Misleading therapeutic guidance resulting in ineffective treatment and frustration"}},{"i":"R3013","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Machine learning reproducibility crisis","s":"AI hype has researchers in fields from medicine to political science rushing to use techniques that they don’t always understand—causing a wave of spurious results. History shows civil wars to be among the messiest, most horrifying of human affairs. So Princeton professor Arvind Narayanan and his PhD student Sayash Kapoor got suspicious last year when they discovered a strand of political science research claiming to predict when a civil war will break out with more than 90 percent accuracy, thanks to artificial intelligence A series of papers described astonishing results from using machine learning , the technique beloved by tech giants that underpins modern AI.","u":"https://www.wired.com/story/machine-learning-reproducibility-crisis/","d":"2022-08-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-11","organization":"Princeton professor Arvind Narayanan and his PhD student Sayash Kapoor","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"Researchers in fields from medicine to political science","action":"Used machine learning techniques to predict civil wars","consequence":"Spurious results and misleading predictions"}},{"i":"R3014","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Amazon irobot roomba acquisition data privacy","s":"Why is the Roomba company worth $1.7 billion to Amazon? It’s not the dust, it’s the data. After decades of creating war machines and home cleaning appliances , iRobot agreed to be acquired by Amazon for $1.7 billion, according to a joint statement by the two companies. If the deal goes through, it would give Amazon access to yet another wellspring of personal data: interior maps of Roomba owners’ homes. iRobot got its start building robots for the US military , but 20 years ago added consumer vacuums to the mix. (It spun off the defense business altogether in 2016.) Those Roombas work in part by using sensors to map the homes they operate in.","u":"https://www.wired.com/story/amazon-irobot-roomba-acquisition-data-privacy/","d":"2022-08-05","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-08-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-05","organization":"iRobot","aiSystem":"Roomba's mapping technology","affectedGroup":"Roomba owners","action":"Used sensors to map Roomba owners' homes","consequence":"Gave Amazon access to personal data"}},{"i":"R3015","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Cruises robot car outages","s":"In a series of incidents, the GM subsidiary lost contact with its autonomous vehicles, leaving them frozen in traffic and trapping human drivers. Around midnight on June 28, Calvin Hu was driving with his girlfriend near San Francisco’s Golden Gate Park when he pulled up at an intersection behind two white and orange autonomous Chevrolet Bolts operated by Cruise, a subsidiary of General Motors Another was stopped to his right in the adjacent lane. The light turned green but the cars, which operate in the city without drivers , didn’t move. When Hu prepared to reverse and go around the frozen vehicles, he says, he noticed that several more Cruise vehicles had stopped in the lanes behind him.","u":"https://www.wired.com/story/cruises-robot-car-outages/","d":"2022-07-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-28","organization":"General Motors and Cruise","aiSystem":"Autonomous Chevrolet Bolts operated by Cruise, a subsidiary of General Motors","affectedGroup":"Human drivers","action":"Autonomous vehicles failed to move when the light turned green","consequence":"Human drivers were trapped in traffic and had to reverse their vehicles"}},{"i":"R3016","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Roe abortion sex worker policy","s":"FOSTA/SESTA laws deplatformed sex workers and set the stage to overturn Roe v. Wade. Friday’s Supreme Court decision to overturn Roe v. Wade is one of the most devastating rulings to come out of Washington. It’s also the next step in a larger campaign to expand state surveillance and erode the right to privacy—a campaign that sex workers have been fighting for decades. It’s not a stretch to connect abortion to sex work; Justice Samuel Alito even writes in the majority opinion for Dobbs v. Jackson Women’s Health Organization that the right to terminate a pregnancy “could license fundamental rights to illicit drug use, prostitution, and the like.”","u":"https://www.wired.com/story/roe-abortion-sex-worker-policy/","d":"2022-06-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-29","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"People who engage in sex work","action":"Expanded state surveillance and erosion of privacy rights","consequence":"Increased risk of surveillance and tracking"}},{"i":"R3018","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Airfare prediction tools","s":"The world's current weirdness has made it more difficult for tools like Kayak and Google Flights to guess the best time to buy a plane ticket. Flying has always been a pain: the endless security lines, the hip-checking other passengers to make sure there’s overhead room for your rolly bag, the squeezing into a seat, the ear-popping, the spotty internet, the boredom. But these days, the irritation begins much earlier, when passengers start to look for tickets. The average round-trip ticket price in the US was $408 this week, up $100 from the same time in 2019, according to the airfare sales app Hopper. Part of that is pent-up demand from people sick of their homes after a still-not-over pandemic Another is high fuel prices, spurred upward by the war in Ukraine.","u":"https://www.wired.com/story/airfare-prediction-tools/","d":"2022-06-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-03","organization":"Kayak and Google Flights","aiSystem":"Airfare prediction tools","affectedGroup":"Passengers","action":"Predicted flight prices","consequence":"Increased ticket prices"}},{"i":"R3020","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Nypd spot boston dynamics robot dog","s":"Plus: Google Maps enhances coverage within US national parks, SwiftKey with Bing Chat lands on iPhones, and we track the rise of the AI voice clones. Our old friend Spot the robot dog is joining the Big Apple's police force. New York City mayor Eric Adams announced that the New York Police Department will be acquiring some new semi-autonomous robotic canines in the coming weeks. The move comes almost exactly two years after the NYPD halted its first go at using a camera-carrying robot dog for surveillance, after a massive public outcry; citizens felt it was a dystopian overreach of police power. Now Adams, a former NYPD captain, is moving the program forward again.","u":"https://www.wired.com/story/nypd-spot-boston-dynamics-robot-dog/","d":"2022-04-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-04-15","organization":"New York Police Department","aiSystem":"semi-autonomous robotic canines","affectedGroup":"citizens","action":"used for surveillance","consequence":"felt it was a dystopian overreach of police power"}},{"i":"R3023","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Hidden role facial recognition tech arrests","s":"The technology is spreading fast among police, and often wrong. But people charged with crimes are rarely told an algorithm came into play. Application Face recognition End User Government Sector Public safety Source Data Images Technology Machine vision In April 2018, Bronx public defender Kaitlin Jackson was assigned to represent a man accused of stealing a pair of socks from a TJ Maxx store. The man said he couldn’t have stolen the socks because at the time the theft occurred, he was at a hospital about three-quarters of a mile away, where his son was born about an hour later. Jackson couldn’t understand how police had identified and arrested her client months after the theft.","u":"https://www.wired.com/story/hidden-role-facial-recognition-tech-arrests/","d":"2022-03-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"April 2018","organization":"Police authorities","aiSystem":"Facial recognition technology","affectedGroup":"Individual accused of theft","action":"Used facial recognition to identify and arrest","consequence":"Wrongful detention"}},{"i":"R3026","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Artificial emotional intelligence","s":"Technology used to only deliver our messages. Now it wants to write them for us by understanding our emotions. In May 2021, Twitter, a platform notorious for abuse and hot-headedness, rolled out a “prompts” feature that suggests users think twice before sending a tweet. The following month, Facebook announced AI “conflict alerts” for groups, so that admins can take action where there may be “contentious or unhealthy conversations taking place.” Email and messaging smart-replies finish billions of sentences for us every day. Amazon’s Halo, launched in 2020, is a fitness band that monitors the tone of your voice. Wellness is no longer just the tracking of a heartbeat or the counting of steps, but the way we come across to those around us.","u":"https://www.wired.com/story/artificial-emotional-intelligence/","d":"2021-12-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-12-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-06","organization":"Facebook","aiSystem":"Emotionally intelligent AI assistant","affectedGroup":"Group administrators","action":"Deployed AI conflict alerts","consequence":"May lead to contentious or unhealthy conversations"}},{"i":"R3028","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"3 years maven uproar google warms pentagon","s":"The company has contracts to detect corrosion on Navy ships and help maintain Air Force jets. Now it wants to bid for a lucrative cloud contract. In 2018, thousands of Google employees protested a Pentagon contract dubbed Project Maven that used the company’s artificial intelligence technology to analyze drone surveillance footage. Google said it wouldn’t renew the contract and announced guiding principles for future AI projects that forbid work on weapons and surveillance projects “violating internationally accepted norms.” At the same time, Google made clear it would still seek defense contracts. “While we are not developing AI for use in weapons,” CEO Sundar Pichai wrote, “we will continue our work with governments and the military in many other areas.”","u":"https://www.wired.com/story/3-years-maven-uproar-google-warms-pentagon/","d":"2021-11-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018","organization":"Google","aiSystem":"Google's artificial intelligence technology","affectedGroup":"Google employees","action":"Used AI to analyze drone surveillance footage","consequence":"Protests and ethical guidelines"}},{"i":"R3029","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Amazon failed to protect your data investigation","s":"Voyeurs. Sabotaged accounts. Backdoor schemes. For years, the retail giant has handled your information less carefully than it handles your packages. On September 26, 2018, a row of tech executives filed into a marble- and wood-paneled hearing room and sat down behind a row of tabletop microphones and tiny water bottles. They had all been called to testify before the US Senate Commerce Committee on a dry subject—the safekeeping and privacy of customer data—that had recently been making large numbers of people mad as hell. Committee chair John Thune, of South Dakota, gaveled the hearing to order, then began listing events from the past year that had shown how an economy built on data can go luridly wrong.","u":"https://www.wired.com/story/amazon-failed-to-protect-your-data-investigation/","d":"2021-11-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018-09-26","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"Customers","action":"Failed to protect customer data","consequence":"Data mishandling leading to privacy issues"}},{"i":"R3030","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Company tapped ai website landed court","s":"Under pressure to make their sites accessible to visually impaired users, firms turn to software. But advocates say the tech isn't always up to the task. Last year, Anthony Murphy, a visually impaired man who lives in Erie, Pennsylvania, visited the website of eyewear retailer Eyebobs using screen reader software. Its synthesized voice attempted to read out the page’s content, as well as navigation buttons and menus. Eyebobs used artificial intelligence software from Israeli startup AccessiBe that promised to make its site easier for people with disabilities to use. But Murphy found it made it harder. AccessiBe says it can simplify the work of making websites accessible to people with impaired vision or other challenges by “replacing a costly, manual process with an automated, state-of-the-art AI technology.”","u":"https://www.wired.com/story/company-tapped-ai-website-landed-court/","d":"2021-11-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-11","organization":"Eyebobs (eyewear retailer)","aiSystem":"Artificial intelligence software from Israeli startup AccessiBe","affectedGroup":"Visually impaired users","action":"Used artificial intelligence software to make the website easier to navigate for people with disabilities","consequence":"Made it harder for a visually impaired user to navigate the website"}},{"i":"R3033","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Nypd secret fund surveillance tools","s":"Documents reveal that police bought facial-recognition software, vans equipped with x-ray machines, and “stingray” cell site simulators—with no public oversight. New York City police bought a range of surveillance tools—including facial-recognition software, predictive policing software, vans equipped with x-ray machines to detect weapons, and “stingray” cell site simulators—with no public oversight, according to documents released Tuesday. In all, the documents show that the NYPD spent at least $159 million since 2007 through a little-known “Special Expenses Fund” that did not require approval by the city council or other municipal officials.","u":"https://www.wired.com/story/nypd-secret-fund-surveillance-tools/","d":"2021-08-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-08-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-08-10","organization":"New York City Police Department (NYPD)","aiSystem":"Facial recognition software, predictive policing software, x-ray vans, stingray cell site simulators","affectedGroup":"General public","action":"Bought and deployed surveillance tools without public oversight","consequence":"Exposure to invasive surveillance technologies"}},{"i":"R3034","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Algorithm predicts deadly infections often flawed","s":"A study found that a system used to identify cases of sepsis missed most instances and frequently issued false alarms. A complication of infection known as sepsis is the number one killer in US hospitals. So it’s not surprising that more than 100 health systems use an early warning system offered by Epic Systems, the dominant provider of US electronic health records. The system throws up alerts based on a proprietary formula tirelessly watching for signs of the condition in a patient’s test results. But a new study using data from nearly 30,000 patients in University of Michigan hospitals suggests Epic’s system performs poorly.","u":"https://www.wired.com/story/algorithm-predicts-deadly-infections-often-flawed/","d":"2021-06-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-06-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-06-21","organization":"Epic Systems","aiSystem":"Epic Systems' early warning system","affectedGroup":"Patients in University of Michigan hospitals","action":"issued false alarms","consequence":"missed most instances of sepsis and caused false alarms"}},{"i":"R3037","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Opinion new york citys surveillance battle offers national lessons","s":"A lack of police transparency highlights how citizens need to remain vigilant to take back control over their privacy. In January, when New York’s Public Oversight of Surveillance Technology Act went into effect, the City of New York Police Department was suddenly forced to detail the tools it had long kept from public view. But instead of giving New Yorkers transparency, the NYPD gave error-filled, boilerplate statements that hide almost everything of value. Almost none of the policies list specific vendors, surveillance tool models, or information-sharing practices. The department’s facial recognition policy says it can share data “pursuant to on-going criminal investigations, civil litigation, and disciplinary proceedings,” a standard so broad it’s largely meaningless.","u":"https://www.wired.com/story/opinion-new-york-citys-surveillance-battle-offers-national-lessons/","d":"2021-02-12","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-02-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"January","organization":"New York City Police Department","aiSystem":"Facial recognition technology","affectedGroup":"Citizens","action":"Provided vague and incomplete policy statements","consequence":"Failed to provide transparency and detailed information"}},{"i":"R3040","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Rent robot worker less paying human","s":"Automation is reaching more companies, imperiling some jobs and changing the nature of others. Polar Manufacturing has been making metal hinges, locks, and brackets in south Chicago for more than 100 years. Some of the company’s metal presses—hulking great machines that loom over a worker—date from the 1950s. Last year, to meet rising demand amid a shortage of workers, Polar hired its first robot employee. The robot arm performs a simple, repetitive job: lifting a piece of metal into a press, which then bends the metal into a new shape. And like a person, the robot worker gets paid for the hours it works. Jose Figueroa, who manages Polar’s production line, says the robot, which is leased from a company called Formic, costs the equivalent of $8 per hour, compared with a minimum wage of $15 per hour for a human employee.","u":"https://www.wired.com/story/rent-robot-worker-less-paying-human/","d":"2021-01-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-01-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-22","organization":"Polar Manufacturing","aiSystem":"Not specified in report","affectedGroup":"Human employees","action":"Robot arm performs a simple, repetitive job of lifting metal into a press","consequence":"Robot worker gets paid less than a human employee"}},{"i":"R3041","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Job screening service halts facial analysis applicants","s":"But it’s still using intonation and behavior to assist with hiring decisions. Job hunters may now need to impress not just prospective bosses but artificial intelligence algorithms too—as employers screen candidates by having them answer interview questions on a video that is then assessed by a machine. HireVue, a leading provider of software for vetting job candidates based on an algorithmic assessment, said Tuesday it is killing off a controversial feature of its software: analyzing a person’s facial expressions in a video to discern certain characteristics. Job seekers screened by HireVue sit in front of a webcam and answer questions.","u":"https://www.wired.com/story/job-screening-service-halts-facial-analysis-applicants/","d":"2021-01-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-01-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-12","organization":"HireVue","aiSystem":"HireVue, a leading provider of software for vetting job candidates based on an algorithmic assessment","affectedGroup":"Job applicants","action":"analyzing a person’s facial expressions in a video to discern certain characteristics","consequence":"killing off a controversial feature of its software"}},{"i":"R1009","k":"Venezuela","p":"Venezuela","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Fake news ai avatars synthesia","s":"A character actor whose face you may have seen in some movies or shows had suddenly found himself out of work during the pandemic. To make a few bucks, he took on a gig that sounded a little iffy but hey, he needed the money. He sold his likeness to an AI company. The company […]. The company promised his likeness would not be used for anything nefarious. Now his face is being used in propaganda churned out by dictatorships. He’s not the only one. Dan Dewhirst is that actor. He had a small role in the Alien prequel Prometheus and was in the short-lived Netflix series The Dark Crystal: Age of Resistance During the pandemic, he was approached by a London-based AI startup called Synthesia.","u":"https://www.vice.com/en/article/fake-news-ai-avatars-synthesia/","d":"2024-10-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-17","organization":"London-based AI startup Synthesia","aiSystem":"Synthesia AI","affectedGroup":"character actor Dan Dewhirst","action":"sold his likeness to Synthesia","consequence":"his likeness used in propaganda by dictatorships"}},{"i":"R2082","k":"Venezuela","p":"Venezuela","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Us military anthropic ai model claude venezuela raid","s":"Wall Street Journal says Claude used in operation via Anthropic’s partnership with Palantir Technologies. Claude, the AI model developed by Anthropic, was used by the US military during its operation to kidnap Nicolás Maduro from Venezuela, the Wall Street Journal revealed on Saturday, a high-profile example of how the US defence department is using artificial intelligence in its operations. The US raid on Venezuela involved bombing across the capital, Caracas, and the killing of 83 people, according to Venezuela’s defence ministry. Anthropic’s terms of use prohibit the use of Claude for violent ends, for the development of weapons or for conducting surveillance.","u":"https://www.theguardian.com/technology/2026/feb/14/us-military-anthropic-ai-model-claude-venezuela-raid","d":"2026-02-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-14","organization":"US military, US defence department","aiSystem":"Claude, the AI model developed by Anthropic","affectedGroup":"Nicolás Maduro","action":"Kidnapped Nicolás Maduro","consequence":"Exposure to violence and death"}},{"i":"R2434","k":"Venezuela","p":"Venezuela","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Us military anthropic ai model claude venezuela raid","s":"Wall Street Journal says Claude used in operation via Anthropic’s partnership with Palantir Technologies. Claude, the AI model developed by Anthropic, was used by the US military during its operation to kidnap Nicolás Maduro from Venezuela, the Wall Street Journal revealed on Saturday, a high-profile example of how the US defence department is using artificial intelligence in its operations. The US raid on Venezuela involved bombing across the capital, Caracas, and the killing of 83 people, according to Venezuela’s defence ministry. Anthropic’s terms of use prohibit the use of Claude for violent ends, for the development of weapons or for conducting surveillance.","u":"https://www.theguardian.com/technology/2026/feb/14/us-military-anthropic-ai-model-claude-venezuela-raid","d":"2026-02-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-14","organization":"US military, US defence department","aiSystem":"Claude, the AI model developed by Anthropic","affectedGroup":"Nicolás Maduro, 83 people killed in Venezuela","action":"Used Claude to kidnap Nicolás Maduro during military operation in Venezuela","consequence":"Kidnapping of Nicolás Maduro, killing of 83 people in Venezuela"}},{"i":"R1509","k":"Vietnam","p":"Vietnam","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Vietnam police catch ring using biometric face spoof to launder 39m","s":"Vietnam is adapting its rules for online account security as the country leans into digital transformation, but fraudsters are also innovating. Vietnam is adapting its rules for online account security as the country leans into digital transformation for government and business, but fraudsters are also innovating with fresh techniques. Police in Vietnam have arrested a 14-member gang for allegedly laundering VND 1 trillion ($38.4 million) using generative AI to defeat biometric security measures at banks, according to VN Express The gang, led by 46-year-old Pham Hong Chuyen from Hanoi, are under investigation for organizing illegal gambling from their bases in Hanoi and Ninh Binh province, according to Ninh Binh police, and are being questioned for money laundering.","u":"https://www.biometricupdate.com/202506/vietnam-police-catch-ring-using-biometric-face-spoof-to-launder-39m","d":"2025-06-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-02","organization":"Police in Vietnam","aiSystem":"Generative AI","affectedGroup":"Fraudsters","action":"Used generative AI to defeat biometric security measures","consequence":"Laundered VND 1 trillion ($38.4 million)"}},{"i":"R1600","k":"Vietnam","p":"Vietnam","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Cybercriminals use malware to obtain face biometrics break into banking apps","s":"Chinese cybercrime group GoldFactory is creating malware to attack Android and iOS that steals face biometrics and uses them to break into bank accounts of the victim, according to The Register The group started releasing trojanized smartphone apps in June 2023. The first version, GoldDigger, focused on getting banking credentials. The latest version, GoldPickaxe or GoldPickaxe.iOS for Android a. nd iOS, first appeared in October of that same year. It captures data used for identity verification, including face biometrics. Bleeping Computer says that Group-IB , a team of researchers investigating the attacks, believes cybercriminals harvest biometric data that users provide for verification in the apps, then use it to log into accounts on legitimate banking apps in Vietnam and Thailand.","u":"https://www.biometricupdate.com/202402/cybercriminals-use-malware-to-obtain-face-biometrics-break-into-banking-apps","d":"2024-02-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10","organization":"Cybercrime group GoldFactory","aiSystem":"Malware","affectedGroup":"Bank account holders in Vietnam and Thailand","action":"Steals face biometrics and uses them to gain unauthorized access to bank accounts","consequence":"Exposes victims' personal information and financial records, leading to potential financial loss"}}]);
